with flagged as (select *, case when txn_time - lag(txn_time) over (partition by txn_type order by txn_time, id) > interval 14 days then 1 else 0 end as is_new_session from transactions), sessions_transactions as (select *, sum(is_new_session) over (partition by txn_type order by txn_time, id rows between unbounded preceding and current row) as session_id from flagged) select id, account_id, txn_type, amount, merchant, is_new_session, session_id from sessions_transactions order by account_id desc;
